namespace UI_Desktop.Store;

internal static class StoreWarpHeaderHtml
{
	internal static string Styles => ".nestg-warp-control {\n    position: relative;\n    display: inline-flex;\n    align-items: center;\n    gap: 9px;\n    min-width: 0;\n    padding-left: 14px;\n    flex: 0 0 auto;\n    color: #f5f7fc;\n    font-family: \"Segoe UI Variable Text\", \"Segoe UI\", Arial, sans-serif;\n}\n.nestg-warp-control::before {\n    content: \"\";\n    position: absolute;\n    top: 50%;\n    left: 0;\n    width: 1px;\n    height: 28px;\n    background: #354258;\n    transform: translateY(-50%);\n}\n.nestg-brand-warp { display: flex; align-items: center; gap: 11px; min-width: 0; }\n.nestg-header-account { justify-self: end; min-width: 0; }\n.nestg-warp-label { font-size: 14px; font-weight: 800; letter-spacing: .025em; white-space: nowrap; }\n.nestg-warp-switch {\n    position: relative;\n    width: 48px;\n    height: 44px;\n    padding: 0;\n    flex: 0 0 auto;\n    border: 0;\n    background: transparent;\n    cursor: pointer;\n    touch-action: manipulation;\n}\n.nestg-warp-switch::before {\n    content: \"\";\n    position: absolute;\n    inset: 10px 0;\n    border: 1px solid #414d62;\n    border-radius: 999px;\n    background: #30394e;\n    box-shadow: inset 0 1px 4px rgba(0, 0, 0, .3), 0 1px 4px rgba(0, 0, 0, .15);\n    transition: background-color .16s ease, border-color .16s ease, box-shadow .16s ease;\n}\n.nestg-warp-switch:hover:not(:disabled)::before { border-color: #8298b5; }\n.nestg-warp-switch:focus-visible,\n.nestg-warp-install:focus-visible { outline: 2px solid #66c0f4; outline-offset: 2px; }\n.nestg-warp-switch[aria-checked=\"true\"]::before {\n    background: #2b96bf;\n    border-color: #90def5;\n    box-shadow: inset 0 0 5px rgba(255, 255, 255, .23),\n        0 0 0 1px rgba(104, 210, 246, .25), 0 0 10px rgba(73, 190, 234, .6);\n}\n.nestg-warp-control:has(.nestg-warp-switch[aria-checked=\"true\"]) .nestg-warp-label {\n    color: #e8faff;\n    text-shadow: 0 0 7px rgba(106, 211, 246, .45);\n}\n.nestg-warp-switch:disabled { cursor: default; opacity: .7; }\n.nestg-warp-switch[role=\"button\"]::before { border-color: #7693b2; }\n.nestg-warp-icon {\n    position: absolute;\n    top: 15px;\n    right: 5px;\n    width: 14px;\n    height: 14px;\n    color: #bad4e7;\n    pointer-events: none;\n}\n.nestg-warp-icon svg { width: 100%; height: 100%; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.nestg-warp-switch[aria-checked=\"true\"] .nestg-warp-icon { right: auto; left: 5px; color: #e8faff; }\n.nestg-warp-thumb {\n    position: absolute;\n    top: 13px;\n    left: 5px;\n    width: 18px;\n    height: 18px;\n    border-radius: 50%;\n    background: #f7f9ff;\n    box-shadow: 0 1px 5px rgba(0, 0, 0, .35), 0 0 6px rgba(255, 255, 255, .4);\n    transition: transform .16s ease, box-shadow .16s ease;\n}\n.nestg-warp-switch[aria-checked=\"true\"] .nestg-warp-thumb {\n    transform: translateX(20px);\n    box-shadow: 0 1px 5px rgba(0, 0, 0, .35), 0 0 9px rgba(242, 253, 255, .85);\n}\n.nestg-warp-control[aria-busy=\"true\"] .nestg-warp-thumb::after {\n    content: \"\";\n    position: absolute;\n    inset: 3px;\n    border: 2px solid #247fa6;\n    border-right-color: transparent;\n    border-radius: 50%;\n    animation: nestg-warp-busy .7s linear infinite;\n}\n@keyframes nestg-warp-busy { to { transform: rotate(360deg); } }\n.nestg-warp-status {\n    position: absolute;\n    width: 1px;\n    height: 1px;\n    padding: 0;\n    overflow: hidden;\n    clip-path: inset(50%);\n    white-space: nowrap;\n}\n.nestg-warp-install {\n    min-height: 44px;\n    padding: 0;\n    border: 0;\n    background: transparent;\n    color: #9addff;\n    font: inherit;\n    font-size: 11px;\n    font-weight: 700;\n    white-space: nowrap;\n    cursor: pointer;\n}\n.nestg-warp-install:disabled { cursor: default; opacity: .65; }\n.nestg-warp-install-short { display: none; }\n@media (max-width: 1180px) {\n    body:has(.profile-chrome), body:has(.orders-chrome), body:has(.wallet-chrome) { min-width: 0; }\n    .profile-chrome, .orders-chrome, .wallet-chrome {\n        grid-template-columns: minmax(0, 1fr) auto auto;\n        grid-template-rows: auto auto;\n    }\n    .profile-chrome > .nestg-brand-warp, .orders-chrome > .nestg-brand-warp,\n    .wallet-chrome > .nestg-brand-warp { grid-column: 1; grid-row: 1; }\n    .profile-chrome > .nestg-header-account, .orders-chrome > .nestg-header-account,\n    .wallet-chrome > .nestg-header-account { grid-column: 2; grid-row: 1; }\n    .profile-chrome > .window-controls, .orders-chrome > .window-controls,\n    .wallet-chrome > .window-controls { grid-column: 3; grid-row: 1; }\n    .profile-chrome > .profile-nav, .orders-chrome > .orders-nav,\n    .wallet-chrome > .wallet-nav { grid-column: 1 / -1; grid-row: 2; justify-self: start; }\n}\n@media (max-width: 940px) {\n    .chrome { grid-template-columns: auto minmax(0, 1fr) auto; grid-template-rows: auto auto; }\n    .chrome > .nestg-brand-warp { grid-column: 1; grid-row: 1; }\n    .chrome > .nestg-header-account { grid-column: 2; grid-row: 1; }\n    .chrome > .window-buttons { grid-column: 3; grid-row: 1; }\n    .chrome > nav { grid-column: 1 / -1; grid-row: 2; justify-self: center; }\n}\n@media (max-width: 520px) {\n    .profile-chrome, .orders-chrome, .wallet-chrome { padding-inline: 10px; gap: 8px; }\n    .profile-chrome .brand-copy small, .orders-chrome .brand-copy small,\n    .wallet-chrome .brand-copy small { display: none; }\n    .profile-chrome .window-button:first-child, .orders-chrome .window-button:first-child,\n    .wallet-chrome .window-button:first-child { display: none; }\n    .nestg-brand-warp { gap: 7px; }\n    .nestg-warp-control { gap: 6px; padding-left: 8px; }\n    .nestg-warp-label { font-size: 12px; }\n    .nestg-warp-switch { width: 44px; }\n    .nestg-warp-thumb { left: 4px; }\n    .nestg-warp-icon { right: 3px; width: 12px; }\n    .nestg-warp-switch[aria-checked=\"true\"] .nestg-warp-icon { left: 4px; }\n    .nestg-warp-switch[aria-checked=\"true\"] .nestg-warp-thumb { transform: translateX(18px); }\n    .nestg-warp-control:has(.nestg-warp-install:not([hidden])) .nestg-warp-label { display: none; }\n    .nestg-warp-install-full { display: none; }\n    .nestg-warp-install-short { display: inline; }\n}\n@media (prefers-reduced-motion: reduce) {\n    .nestg-warp-switch::before, .nestg-warp-thumb { transition: none; }\n    .nestg-warp-control[aria-busy=\"true\"] .nestg-warp-thumb::after { animation: none; }\n}";

	internal static string Script => "(() => {\n    const applyState = state => {\n        const control = document.querySelector('[data-warp-control]');\n        if (!control || !state) return;\n        const toggle = control.querySelector('[data-warp-switch]');\n        const status = control.querySelector('[data-warp-status]');\n        const install = control.querySelector('[data-warp-install]');\n        if (!toggle || !status || !install) return;\n        const busy = Boolean(state.busy) || state.kind === 'Connecting';\n        control.setAttribute('aria-busy', String(busy));\n        const missing = state.kind === 'NotInstalled';\n        toggle.setAttribute('role', missing ? 'button' : 'switch');\n        toggle.setAttribute('aria-label', missing ? 'Cài Cloudflare WARP để dùng công tắc NestG' : 'Bật hoặc tắt Cloudflare WARP');\n        if (missing) toggle.removeAttribute('aria-checked');\n        else toggle.setAttribute('aria-checked', String(Boolean(state.connected)));\n        toggle.disabled = busy || !(Boolean(state.canToggle) || missing);\n        toggle.title = 'Cloudflare WARP: ' + (busy ? 'Đang xử lý' : (state.detail || state.label || 'Chưa rõ'));\n        status.textContent = state.busy ? 'Đang xử lý' : (state.label || 'Chưa rõ');\n        install.hidden = !missing;\n        install.disabled = busy;\n    };\n    const bind = () => {\n        const control = document.querySelector('[data-warp-control]');\n        const toggle = control?.querySelector('[data-warp-switch]');\n        if (!toggle) return;\n        const install = control.querySelector('[data-warp-install]');\n        const markBusy = () => {\n            toggle.disabled = true;\n            if (install) install.disabled = true;\n            control.setAttribute('aria-busy', 'true');\n            toggle.title = 'Cloudflare WARP: Đang xử lý';\n            control.querySelector('[data-warp-status]').textContent = 'Đang xử lý';\n        };\n        toggle.addEventListener('click', () => {\n            if (toggle.disabled) return;\n            markBusy();\n            if (toggle.getAttribute('role') === 'button') {\n                window.chrome?.webview?.postMessage({ type: 'installWarp' });\n                return;\n            }\n            const enabled = toggle.getAttribute('aria-checked') !== 'true';\n            window.chrome?.webview?.postMessage({ type: 'setWarpEnabled', enabled });\n        });\n        install?.addEventListener('click', event => {\n            if (event.currentTarget.disabled) return;\n            markBusy();\n            window.chrome?.webview?.postMessage({ type: 'installWarp' });\n        });\n    };\n    window.__nestgWarp = { setState: applyState };\n    if (document.readyState === 'loading')\n        document.addEventListener('DOMContentLoaded', bind, { once: true });\n    else bind();\n})();";

	internal static string Render()
	{
		return "<div class=\"nestg-warp-control\" data-warp-control aria-busy=\"true\">\n    <span class=\"nestg-warp-label\" id=\"nestg-warp-label\">WARP</span>\n    <button type=\"button\" class=\"nestg-warp-switch\" role=\"switch\" data-warp-switch\n        aria-label=\"Bật hoặc tắt Cloudflare WARP\" aria-describedby=\"nestg-warp-status\"\n        aria-checked=\"false\" title=\"Đang kiểm tra Cloudflare WARP\" disabled>\n        <span class=\"nestg-warp-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 20 20\" fill=\"none\"><path d=\"M5 15h10a3 3 0 0 0 .2-6 5 5 0 0 0-9.7-1.1A3.6 3.6 0 0 0 5 15Z\"/></svg>\n        </span>\n        <span class=\"nestg-warp-thumb\" aria-hidden=\"true\"></span>\n    </button>\n    <span class=\"nestg-warp-status\" id=\"nestg-warp-status\" data-warp-status\n        role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">Đang kiểm tra</span>\n    <button type=\"button\" class=\"nestg-warp-install\" data-warp-install\n        aria-label=\"NestG giúp cài Cloudflare WARP\"\n        title=\"NestG giúp cài Cloudflare WARP\" hidden>\n        <span class=\"nestg-warp-install-full\">Cài WARP</span>\n        <span class=\"nestg-warp-install-short\">Cài</span>\n    </button>\n</div>";
	}
}
